import { test, expect } from "../helpers/system-control-browser";
import AxeBuilder from "@axe-core/playwright";
for (const route of ["privacy", "terms"]) {
  test(`public ${route} page is readable and accessible`, async ({ page }) => {
    await page.goto(`/${route}`);
    await expect(page.getByRole("heading", { level: 1 })).toHaveText(
      route === "privacy" ? "Privacy Policy" : "Terms of Service",
    );
    await expect(page.getByRole("main")).toContainText("Czar16");
    await expect(page.getByRole("main")).toContainText("[REDACTED_EMAIL]");
    const main = page.getByRole("main");
    for (const text of [
      "30 elapsed days",
      "15-minute",
      "daily cleanup",
      "original request",
      "Pricing",
      "No refunds, except where required by applicable law.",
      "Unused emails do not roll over.",
      "Merchant of Record",
      "₹299/month",
      "US$5.99/month",
      "Includes applicable tax.",
      "Suspension does not",
      "Mark replied",
      "Each email gets one sending attempt",
      "recipients’ requests not to be contacted",
    ])
      await expect(main).toContainText(text);
    await expect(main).toContainText(
      route === "privacy"
        ? "Free includes 15 emails/month and 3/UTC day; Premium includes 300/month and 20/UTC day."
        : // The isolated database starts with paid gating disabled; Terms also supports that legacy rollout state.
          /Free includes 15 emails\/month, 3\/day and 3\/campaign\. Premium includes 300\/month, 20\/day and 10\/campaign\.|Send up to 10 recipients per campaign, within 200 emails per rolling 24 hours\./,
    );
    if (route === "terms") {
      for (const [label, free, premium] of [
        ["Monthly emails", "15", "300"],
        ["Emails per UTC day", "3", "20"],
        ["Recipients per campaign", "3", "10"],
      ]) {
        const row = page.getByRole("row").filter({
          has: page.getByRole("rowheader", { name: label, exact: true }),
        });
        await expect(row.getByRole("cell").nth(0)).toHaveText(free);
        await expect(row.getByRole("cell").nth(1)).toHaveText(premium);
      }
    }
    await expect(main).not.toContainText("90 days");
    await expect(main).toContainText(
      route === "privacy"
        ? "Effective November 11, 2026"
        : "Effective October 21, 2026",
    );
    if (route === "privacy") {
      await expect(main.locator("#google-data-sharing")).toContainText(
        "Sharing and disclosure of Google user data",
      );
      await expect(main.locator("#data-protection")).toContainText(
        "AES-256-GCM",
      );
    }
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
    expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    expect((await page.request.get("/api/account/export")).status()).toBe(401);
  });
}
